css/styles.css.new:
#crane-canvas-container {
  width: 100%;
  height: clamp(460px, 74vh, 780px);
  display: block;
  position: relative;
}

#crane-canvas-container canvas {
  display: block;
  width: 100%;
  height: 100%;
  outline: none;
}

/* HUD sovrapposto alla scena: stato della partita, capsule vinte, suggerimento */
.crane-hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  font-family: var(--font-mono);
}

.crane-status {
  position: absolute;
  top: 18px;
  left: 50%;
  transform: translate(-50%, -8px);
  padding: 8px 16px;
  border-radius: 999px;
  background: rgba(11, 10, 18, 0.72);
  border: 1.5px solid rgba(255, 183, 3, 0.75);
  color: #FFE9C2;
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  white-space: nowrap;
  opacity: 0;
  transition: opacity 0.25s ease, transform 0.25s ease;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}

.crane-status.visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

.crane-collection {
  position: absolute;
  top: 20px;
  right: 20px;
  display: grid;
  grid-template-columns: repeat(6, 12px);
  gap: 6px;
  padding: 9px 11px;
  border-radius: 12px;
  background: rgba(11, 10, 18, 0.6);
  border: 1px solid rgba(244, 241, 232, 0.16);
}

.crane-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1.5px solid rgba(244, 241, 232, 0.38);
  transition: background 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease, transform 0.3s ease;
}

.crane-dot.won {
  background: var(--dot, #E63946);
  border-color: var(--dot, #E63946);
  box-shadow: 0 0 10px var(--dot, #E63946);
  transform: scale(1.12);
}

.crane-orbit-hint {
  position: absolute;
  left: 20px;
  bottom: 16px;
  font-size: 0.68rem;
  letter-spacing: 0.04em;
  color: rgba(244, 241, 232, 0.6);
  transition: opacity 0.6s ease;
}

.crane-orbit-hint.gone {
  opacity: 0;
}

.crane-bottom-dashboard {
  background: linear-gradient(180deg, #1B1A28 0%, #111019 100%);
  border-top: 2px solid #2C2A3E;
  padding: 14px 24px;
  display: grid;
  grid-template-columns: 1fr 1.6fr 1fr;

.arcade-dpad-btn {
  width: 48px;
  height: 42px;
  touch-action: none;
  -webkit-tap-highlight-color: transparent;
  background: #25252E;
  border: 2px solid #3E3E4E;

  transform: translateY(4px);
  box-shadow: 0 2px 0 #8B0000;
}

.btn-drop-claw.busy,
.btn-drop-claw:disabled {
  animation: none;
  cursor: default;
  filter: saturate(0.45) brightness(0.72);
  transform: translateY(4px);
  box-shadow: 0 2px 0 #5c0b10;
}

